def find_rectangular_regions(min_size=4):
    found = []
    h, w = len(inp), len(inp[0])
    for rmin in range(h):
        for rmax in range(rmin + 2, h):
            for cmin in range(w):
                for cmax in range(cmin + 2, w):
                    colors_in_rect = set()
                    for r in range(rmin, rmax + 1):
                        for c in range(cmin, cmax + 1):
                            if inp[r][c] != 5:
                                colors_in_rect.add(inp[r][c])

                    if len(colors_in_rect) == 1:
                        color = list(colors_in_rect)[0]
                        count = sum(1 for r in range(rmin, rmax+1) 
                                   for c in range(cmin, cmax+1) 
                                   if inp[r][c] == color)
                        total = (rmax-rmin+1) * (cmax-cmin+1)

                        if total >= min_size:
                            found.append({
                                'color': color, 'rmin': rmin, 'rmax': rmax,
                                'cmin': cmin, 'cmax': cmax,
                                'count': count, 'ratio': count/total,
                                'area': total
                            })

    return found

