def get_components_by_size(color):
    visited = set()
    components = []

    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    coords = [(r,c) for r in range(h) for c in range(w) if inp[r][c] == color]

    for start in sorted(coords):
        if start in visited:
            continue

        stack = [start]
        comp = []
        while stack:
            r,c = stack.pop()
            if (r,c) in visited or inp[r][c] != color:
                continue
            visited.add((r,c))
            comp.append((r,c))

            for dr, dc in directions:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and inp[nr][nc] == color:
                    if (nr,nc) not in visited:
                        stack.append((nr,nc))

        rmin, rmax = min(r for r,c in comp), max(r for r,c in comp)
        cmin, cmax = min(c for r,c in comp), max(c for r,c in comp)
        total_area = (rmax-rmin+1)*(cmax-cmin+1)
        fill_ratio = len(comp)/total_area

        components.append({
            'comp': comp, 'size': len(comp), 
            'ratio': fill_ratio, 
            'bbox': (rmin, cmin, rmax, cmax),
            'total_area': total_area,
            'color': color  # Add color back
        })

    return sorted(components, key=lambda x: -x['size'])

